"use client"

import type * as React from "react"
import { cn } from "cn"
import {
  ColorArea as ColorAreaPrimitive,
  ColorField as ColorFieldPrimitive,
  ColorPicker as ColorPickerPrimitive,
  ColorSlider as ColorSliderPrimitive,
  ColorSwatch as ColorSwatchPrimitive,
  ColorSwatchPicker as ColorSwatchPickerPrimitive,
  ColorSwatchPickerItem as ColorSwatchPickerItemPrimitive,
  ColorThumb as ColorThumbPrimitive,
  ColorWheel as ColorWheelPrimitive,
  ColorWheelTrack,
  Input,
  Label,
  SliderOutput,
  SliderTrack,
  type ColorAreaProps,
  type ColorFieldProps,
  type ColorPickerProps,
  type ColorSliderProps,
  type ColorSwatchPickerItemProps,
  type ColorSwatchPickerProps,
  type ColorSwatchProps,
  type ColorThumbProps,
  type ColorWheelProps,
} from "react-aria-components"

type WithClassName<P> = Omit<P, "className"> & { className?: string }

/** State root: React Aria ColorPicker shares one color value with every part below. */
function ColorPicker(props: ColorPickerProps) {
  return <ColorPickerPrimitive {...props} />
}

function ColorThumb({ className, ...props }: WithClassName<ColorThumbProps>) {
  return (
    <ColorThumbPrimitive
      data-slot="color-picker-thumb"
      className={cn(
        "size-4 rounded-full border-2 border-white shadow-sm ring-1 ring-black/10 outline-none data-[dragging]:size-5 data-[focus-visible]:ring-3 data-[focus-visible]:ring-ring/50",
        className
      )}
      {...props}
    />
  )
}

/** part.area: two-channel saturation/brightness plane. */
function ColorPickerArea({ className, ...props }: WithClassName<ColorAreaProps>) {
  return (
    <ColorAreaPrimitive
      data-slot="color-picker-area"
      className={cn(
        "aspect-square w-full max-w-56 shrink-0 rounded-lg border border-border data-[disabled]:opacity-50",
        className
      )}
      {...props}
    >
      <ColorThumb />
    </ColorAreaPrimitive>
  )
}

/** part.wheel: hue ring. */
function ColorPickerWheel({
  className,
  outerRadius = 96,
  innerRadius = 72,
  ...props
}: WithClassName<Omit<ColorWheelProps, "outerRadius" | "innerRadius">> & {
  outerRadius?: number
  innerRadius?: number
}) {
  return (
    <ColorWheelPrimitive
      data-slot="color-picker-wheel"
      outerRadius={outerRadius}
      innerRadius={innerRadius}
      className={cn("shrink-0 data-[disabled]:opacity-50", className)}
      {...props}
    >
      <ColorWheelTrack className="rounded-full" />
      <ColorThumb />
    </ColorWheelPrimitive>
  )
}

/** part.slider: one channel (hue, alpha, lightness...). */
function ColorPickerSlider({
  className,
  label,
  ...props
}: WithClassName<ColorSliderProps> & { label?: React.ReactNode }) {
  return (
    <ColorSliderPrimitive
      data-slot="color-picker-slider"
      className={cn("flex w-full flex-col gap-1.5 data-[disabled]:opacity-50", className)}
      {...props}
    >
      {label !== undefined && (
        <div className="flex items-center justify-between text-xs font-medium text-muted-foreground">
          <Label>{label}</Label>
          <SliderOutput className="tabular-nums" />
        </div>
      )}
      <SliderTrack className="h-3 w-full rounded-full border border-border">
        <ColorThumb className="top-1/2" />
      </SliderTrack>
    </ColorSliderPrimitive>
  )
}

/** part.field: typed hex (or one channel) value. */
function ColorPickerField({
  className,
  label,
  ...props
}: WithClassName<ColorFieldProps> & { label?: React.ReactNode }) {
  return (
    <ColorFieldPrimitive
      data-slot="color-picker-field"
      className={cn("flex w-full flex-col gap-1.5", className)}
      {...props}
    >
      {label !== undefined && <Label className="text-xs font-medium text-muted-foreground">{label}</Label>}
      <Input className="h-8 w-full min-w-0 rounded-lg border border-input bg-transparent px-2.5 py-1 font-mono text-sm uppercase outline-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:bg-input/30" />
    </ColorFieldPrimitive>
  )
}

function ColorSwatch({ className, ...props }: WithClassName<ColorSwatchProps>) {
  return (
    <ColorSwatchPrimitive
      data-slot="color-picker-swatch"
      className={cn("size-6 rounded-md shadow-[inset_0_0_0_1px_rgb(0_0_0/0.1)]", className)}
      {...props}
    />
  )
}

/** part.swatch-picker: preset colors. */
function ColorPickerSwatches({ className, ...props }: WithClassName<ColorSwatchPickerProps>) {
  return (
    <ColorSwatchPickerPrimitive
      data-slot="color-picker-swatches"
      className={cn("flex flex-wrap gap-1.5", className)}
      {...props}
    />
  )
}

function ColorPickerSwatch({
  className,
  ...props
}: WithClassName<ColorSwatchPickerItemProps>) {
  return (
    <ColorSwatchPickerItemPrimitive
      data-slot="color-picker-swatch-item"
      className={cn(
        "rounded-md outline-none data-[focus-visible]:ring-3 data-[focus-visible]:ring-ring/50 data-[selected]:ring-2 data-[selected]:ring-ring data-[selected]:ring-offset-2 data-[selected]:ring-offset-background",
        className
      )}
      {...props}
    >
      <ColorSwatch />
    </ColorSwatchPickerItemPrimitive>
  )
}

export {
  ColorPicker,
  ColorPickerArea,
  ColorPickerWheel,
  ColorPickerSlider,
  ColorPickerField,
  ColorPickerSwatches,
  ColorPickerSwatch,
  ColorSwatch,
  ColorThumb,
}
